using System.Collections.Concurrent;using EnterpriseDocumentIntelligence.EmbeddingService.Application;using EnterpriseDocumentIntelligence.EmbeddingService.Domain; namespace EnterpriseDocumentIntelligence.EmbeddingService.Infrastructure; public sealed class InMemoryEmbeddingStore:IEmbeddingStore{private readonly ConcurrentDictionary<string,EmbeddingVector> _items=new();public Task SaveAsync(EmbeddingVector v,CancellationToken ct=default){_items[$"{v.DocumentId:N}:{v.ChunkNumber}"]=v;return Task.CompletedTask;}public Task<EmbeddingVector?> GetAsync(Guid d,int c,CancellationToken ct=default)=>Task.FromResult(_items.TryGetValue($"{d:N}:{c}",out var v)?v:null);} public sealed class DeterministicEmbeddingGenerator:IEmbeddingGenerator{public Task<IReadOnlyList<float>> GenerateAsync(string text,CancellationToken ct=default){var hash=System.Security.Cryptography.SHA256.HashData(System.Text.Encoding.UTF8.GetBytes(text));IReadOnlyList<float> values=hash.Take(8).Select(b=>(float)b/255f).ToArray();return Task.FromResult(values);}} public static class EmbeddingServiceInfrastructure{public static IServiceCollection AddEmbeddingApplication(this IServiceCollection services){services.AddSingleton<IEmbeddingStore,InMemoryEmbeddingStore>();services.AddSingleton<IEmbeddingGenerator,DeterministicEmbeddingGenerator>();services.AddScoped<EmbeddingApplication>();return services;}}